    funcs=set() if funcs is None else funcs; labels=set() if labels is None else labels
    errors=[]
    def rec(n,vs,fs,ls):
        if not isinstance(n,Node): return
        k,a=n.kind,n.args
        if k=='call':
            if (a[0],len(a[1])) not in fs and a[0]+'/'+str(len(a[1])) not in known:
                errors.append(CompileError(a[0]+'/'+str(len(a[1]))+' is not defined',n.pos,n.pos+len(a[0])))
        if k=='var' and a[0] not in vs:
            errors.append(CompileError('$'+a[0]+' is not defined',n.pos,n.end))
        if k=='def':
            nfs=fs|{(a[0],len(a[1]))}; bvs=vs|{x for t,x in a[1] if t=='VAR'}; bfs=nfs|{(x,0) for t,x in a[1] if t=='ID'}
            rec(a[2],bvs,bfs,ls); rec(a[3],vs,nfs,ls); return
        if k=='bind':
            rec(a[0],vs,fs,ls); ns=set(sum((pattern_names(p) for p in a[1]),[])); rec(a[2],vs|ns,fs,ls); return
        if k in ('reduce','foreach'):
            rec(a[0],vs,fs,ls); rec(a[2],vs,fs,ls); ns=set(pattern_names(a[1])); rec(a[3],vs|ns,fs,ls); rec(a[4],vs|ns,fs,ls); return
        if k=='label': rec(a[1],vs,fs,ls|{a[0]}); return
        if k=='break':
            if a[0] not in ls: errors.append(CompileError('$*label-'+a[0]+' is not defined',n.pos,n.end))
        def traverse(x):
            if isinstance(x,Node): rec(x,vs,fs,ls)
            elif isinstance(x,(list,tuple)):
                for y in x: traverse(y)
        for x in a: traverse(x)
    rec(node,set(vars),funcs,labels)
    return errors
