def format_value(name,v):
    if name=='text': return tostring(v)
    if name=='json': return dumps(v)
    if name=='html':
        s=tostring(v)
        for c,r in [('&','&amp;'),('<','&lt;'),('>','&gt;'),('"','&quot;'),("'",'&apos;')]: s=s.replace(c,r)
        return s
    if name in ('uri','urid'):
        return urllib.parse.quote(tostring(v),safe="-_.!~*'()") if name=='uri' else urllib.parse.unquote(tostring(v))
    if name=='base64': return base64.b64encode(tostring(v).encode('utf-8')).decode()
    if name=='base64d':
        if not isinstance(v,str): raise JQError(describe(v)+' is not valid base64 data')
        try:
            if re.search(r'[^A-Za-z0-9+/=]',v): raise ValueError()
            return base64.b64decode(v+'='*((-len(v))%4)).decode('utf-8','replace')
        except Exception: raise JQError(describe(v)+' is not valid base64 data')
    if name in ('csv','tsv'):
        if not isinstance(v,list): raise JQError(describe(v)+' cannot be '+name+'-formatted, only array')
        row=[]
        for x in v:
            if x is None or num(x) and math.isnan(float(x)): row.append('')
            elif isinstance(x,str):
                row.append('"'+x.replace('"','""')+'"' if name=='csv' else x.replace('\\','\\\\').replace('\t','\\t').replace('\r','\\r').replace('\n','\\n'))
            elif isinstance(x,(list,dict)): raise JQError(describe(x)+' is not valid in a '+name+' row')
            else: row.append(tostring(x))
        return (',' if name=='csv' else '\t').join(row)
    if name=='sh':
        row=[]
        for x in v if isinstance(v,list) else [v]:
            if isinstance(x,str): row.append("'"+x.replace("'","'\\''")+"'")
            elif isinstance(x,(list,dict)): raise JQError(describe(x)+' can not be escaped for shell')
            else: row.append(tostring(x))
        return ' '.join(row)
    raise JQError(name+' is not a valid format')


def require_array(v,verb='sorted'):
    if not isinstance(v,list): raise JQError(describe(v)+' cannot be '+verb+', as it is not an array')

def tonumber(v):
    if num(v): return v
    if isinstance(v,str):
        if re.fullmatch(r'[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|[Nn][Aa][Nn]|[Ii][Nn][Ff](?:[Ii][Nn][Ii][Tt][Yy])?)',v):
