            except InvalidOperation: pass
    raise JQError(describe(v)+' cannot be parsed as a number')

def regex_compile(pattern,flags):
    if not isinstance(pattern,str): raise JQError(describe(pattern)+' is not a string')
    if flags is None: flags=''
    if not isinstance(flags,str): raise JQError(describe(flags)+' is not a string')
    if any(x not in 'gimnpslx' for x in flags): raise JQError('Invalid regex options: '+flags)
    opts=re.MULTILINE
    if 'i' in flags: opts|=re.IGNORECASE
    if 'm' in flags or 'p' in flags: opts|=re.DOTALL
    if 's' in flags or 'p' in flags: opts&=~re.MULTILINE
    if 'x' in flags: opts|=re.VERBOSE
    pattern=re.sub(r'\(\?<([A-Za-z_][A-Za-z_0-9]*)>',r'(?P<\1>',pattern)
    pattern=re.sub(r"\(\?'([A-Za-z_][A-Za-z_0-9]*)'",r'(?P<\1>',pattern)
    pattern=re.sub(r'\\k<([A-Za-z_][A-Za-z_0-9]*)>',r'(?P=\1)',pattern)
    pattern=pattern.replace('\\z','\\Z')
    try: return re.compile(pattern,opts),flags
    except re.error as ex:
        msg=str(ex).split(' at position')[0]
        translations={'missing ), unterminated subpattern':'end pattern with unmatched parenthesis','unterminated character set':'premature end of char-class','unbalanced parenthesis':'unmatched close parenthesis','nothing to repeat':'target of repeat operator is not specified'}
        raise JQError('Regex failure: '+translations.get(msg,msg))

