        if s is None: c={'offset':-1,'string':None,'length':0,'name':names.get(i)}
        else: c={'offset':m.start(i),'length':len(s),'string':s,'name':names.get(i)}
        captures.append(c)
    return {'offset':m.start(),'length':len(m[0]),'string':m[0],'captures':captures}

