    longs={'null-input':'n','raw-input':'R','slurp':'s','compact-output':'c','raw-output':'r','ascii-output':'a','sort-keys':'S','color-output':'C','monochrome-output':'M','exit-status':'e','join-output':'j','from-file':'f','binary':'b'}
