                else: setattr(o,{'--unbuffered':'unbuffered','--stream':'stream','--stream-errors':'streamerrors','--seq':'seq'}[a],True)
                if a=='--stream-errors': o.stream=True
                i+=1; continue
            if a in ('--arg','--argjson','--slurpfile','--rawfile'):
                if a in ('--arg','--argjson'): msg=a+' takes two parameters (e.g. '+a+' varname '+('value' if a=='--arg' else 'text')+')'
                else: msg=a+' takes two parameters (e.g. '+a+' varname filename)'
