                o.libpaths.append(val); i+=1; continue
            if a=='--run-tests': o.run_tests=True; o.files=argv[i+1:]; break
            if a.startswith('--') and a[2:] in longs: flag(longs[a[2:]]); i+=1; continue
            if not a.startswith('--') and all(ch in opts or ch in 'hV' for ch in a[1:]):
                for ch in a[1:]:
                    if ch=='h': return 'help'
                    if ch=='V': return 'version'
