def compile_errors(errors,source,filename):
    for er in errors:
        pos=max(0,min(er.pos,len(source))); line=source.count('\n',0,pos)+1; start=source.rfind('\n',0,pos)+1
        text=source[start:source.find('\n',start) if '\n' in source[start:] else len(source)]
        col=pos-start+1; length=max(1,min(er.end-pos,len(text)-col+1))
        sys.stderr.write('jq: error: '+er.msg+' at '+filename+', line '+str(line)+', column '+str(col)+':\n')
        sys.stderr.write('    '+text+'\n'+'    '+' '*(col-1)+'^'*length+'\n')
    sys.stderr.write('jq: '+str(len(errors))+' compile error'+('s' if len(errors)!=1 else '')+'\n')


def expand_imports(node,o,vars,loaded=None):
    loaded=set() if loaded is None else loaded
    from jqsyntax import Node
    if node.kind=='import':
        mode,name,alias,meta,rest=node.args
        if name.kind!='lit' or not isinstance(name.args[0],str): raise CompileError('module name must be a string',node.pos,node.end)
        name=name.args[0]; target=None
        paths=o.libpaths+[o.prog_origin]
        extension='.json' if alias and alias in vars and False else '.jq'
        for path in paths:
            path=os.path.expanduser(path.replace('$ORIGIN',os.path.dirname(os.path.abspath(sys.argv[0]))))
            for file in (os.path.join(path,name+extension),os.path.join(path,name,name.split('/')[-1]+extension)):
                if os.path.isfile(file): target=file; break
            if target: break
        if not target: raise CompileError('module not found: '+name,node.pos,node.pos+len(mode))
        if target in loaded: return expand_imports(rest,o,vars,loaded)
        loaded.add(target)
        text=open(target).read()
        try: mod=Parser(text+'\n.').parse()
        except CompileError: mod=Parser(text).parse()
        # Qualify definitions and their internal calls for namespaced imports.
        def qualify(n):
            if not isinstance(n,Node): return n
            vals=[]
            for a in n.args:
                if isinstance(a,Node): vals.append(qualify(a))
                elif isinstance(a,list): vals.append([qualify(x) if isinstance(x,Node) else x for x in a])
                else: vals.append(a)
            if mode=='import' and n.kind in ('def','call'):
                if n.kind=='def' or vals[0] in names: vals[0]=alias+'::'+vals[0]
            return N(n.kind,*vals,pos=n.pos,end=n.end)
        names=set(); ptr=mod
        while ptr.kind=='def': names.add(ptr.args[0]); ptr=ptr.args[3]
