    if o.run_tests: return run_tests(o)
    vars={**o.vars,'ARGS':{'positional':o.positional,'named':o.vars.copy()},'ENV':dict(os.environ),'__loc__':{'file':o.progname,'line':1}}
    try:
        program=Parser(o.program).parse(); program=expand_imports(program,o,vars)
