def run_tests(o):
    count=0; passed=0
    for filename in o.files or ['-']:
        text=sys.stdin.read() if filename=='-' else readfile(filename)
        lines=text.splitlines(); i=0
        while i<len(lines):
            if not lines[i].strip() or lines[i].startswith('#'): i+=1; continue
            line=i+1; f=lines[i]; i+=1
            if i>=len(lines): break
            data=lines[i]; i+=1; expected=[]
            while i<len(lines) and lines[i].strip(): expected.append(lines[i]); i+=1
            count+=1
            print('Testing '+repr(f)+' at line number '+str(line))
            try:
                ctx=SimpleNamespace(filename=None,line=0,inputs=iter([]),prog_origin=o.prog_origin,libpaths=o.libpaths)
